/*
 * Solderless - every peripheral register and field of the STM32G431, from
 * data/g431rb-registers.json (generated by tools/gen_g431.py from ST's SVD
 * and data/field-notes.txt).
 * Copyright (C) 2026 The Solderless authors. GPL-3.0-or-later.
 */
package io.github.leukoplast1980.solderless.chip

import org.json.JSONArray
import org.json.JSONObject

class RegisterMap(json: String) {

    /** One value of a field and what it means; [pattern] is binary, x for either bit. */
    class Value(val pattern: String, val meaning: String) {
        private val mask: Long
        private val bits: Long

        init {
            var m = 0L
            var b = 0L
            for (c in pattern) {
                m = m shl 1; b = b shl 1
                if (c != 'x') { m = m or 1; if (c == '1') b = b or 1 }
            }
            mask = m; bits = b
        }

        fun matches(v: Long) = v and mask == bits

        /** The value written when this one is picked: x bits as 0. */
        val canonical: Long get() = bits
    }

    class Field(
        val name: String, val bit: Int, val width: Int, val access: String,
        val description: String, val about: String, val show: String, val values: List<Value>,
    ) {
        val mask: Long get() = ((1L shl width) - 1) shl bit
        fun of(reg: Long): Long = (reg ushr bit) and ((1L shl width) - 1)
        val readable: Boolean get() = access != "w"
        val writable: Boolean get() = access != "r"
        fun meaning(v: Long): String? = values.firstOrNull { it.matches(v) }?.meaning

        /** The number in the name: MODER5 → 5, OC1M → 1, CCR3 → 3; null if none. */
        val number: Int? get() = Regex("\\d+").find(name)?.value?.toIntOrNull()

        /** "bits 11:10" or "bit 5" */
        val bits: String get() = if (width == 1) "bit $bit" else "bits ${bit + width - 1}:$bit"
    }

    class Register(
        val name: String, val offset: Int, val reset: Long, val access: String,
        val description: String, val fields: List<Field>,
    ) {
        val readable: Boolean get() = access != "w"
        val writableMask: Long get() = fields.filter { it.writable }.fold(0L) { m, f -> m or f.mask }
            .let { if (fields.isEmpty() && access != "r") 0xFFFFFFFFL else it }
    }

    class Peripheral(
        val name: String, val base: Long, val description: String, val registers: List<Register>,
        /** RCC enable register offset and bit; -1: always clocked */
        val enOffset: Int, val enBit: Int,
        /** Not emulated: its registers only keep what is written to them */
        val stored: Boolean,
    ) {
        fun address(r: Register): Long = base + r.offset
        val core: Boolean get() = base >= 0xE0000000L

        /** The GPIO port letter, or null */
        val port: Char? get() = if (name.length == 5 && name.startsWith("GPIO")) name[4] else null

        /** The text of a note with its placeholders filled in */
        fun fill(text: String, f: Field): String =
            text.replace("{n}", f.number?.toString() ?: "").replace("{port}", port?.toString() ?: "x")
    }

    val peripherals: List<Peripheral>

    init {
        val root = JSONObject(json)
        val blocks = root.getJSONObject("blocks")
        val parsed = HashMap<String, List<Register>>()
        fun block(key: String): List<Register> = parsed.getOrPut(key) {
            val a = blocks.getJSONArray(key)
            (0 until a.length()).map { i -> register(a.getJSONObject(i)) }
        }
        val ps = root.getJSONArray("peripherals")
        peripherals = (0 until ps.length()).map { i ->
            val p = ps.getJSONObject(i)
            val en = p.optJSONArray("en")
            Peripheral(
                p.getString("name"), p.getLong("base"), p.optString("d"), block(p.getString("block")),
                en?.getInt(0) ?: -1, en?.getInt(1) ?: -1, p.optBoolean("stored"),
            )
        }
    }

    fun peripheral(name: String): Peripheral? = peripherals.firstOrNull { it.name == name }

    /** The peripheral and register at an address, if any. */
    fun at(address: Long): Pair<Peripheral, Register>? = byAddress[address]

    /** Every register by address; where two peripherals overlap, the first one listed */
    private val byAddress: Map<Long, Pair<Peripheral, Register>> by lazy {
        HashMap<Long, Pair<Peripheral, Register>>().also { m ->
            for (p in peripherals) for (r in p.registers)
                if (r.offset in 0 until 0x1000) m.putIfAbsent(p.base + r.offset, p to r)
        }
    }

    private fun register(o: JSONObject): Register {
        val access = o.getString("a")
        val fa = o.optJSONArray("f") ?: JSONArray()
        val fields = (0 until fa.length()).map { i ->
            val f = fa.getJSONObject(i)
            val va = f.optJSONArray("v")
            val values = if (va == null) emptyList() else (0 until va.length()).map { j ->
                val pair = va.getJSONArray(j)
                Value(pair.getString(0), pair.getString(1))
            }
            Field(
                f.getString("n"), f.getInt("b"), f.getInt("w"), f.optString("a", access),
                f.optString("d"), f.optString("about"), f.optString("show"), values,
            )
        }
        return Register(o.getString("n"), o.getInt("o"), o.getLong("r"), access, o.optString("d"), fields)
    }

    companion object {
        /** RCC's base: the enable registers' offsets are from here */
        const val RCC_BASE = 0x40021000L
    }
}
